def nav_html(prefix=""):
    links = [f'<a href="{prefix}{href}">{label}</a>' for label, href in NAV]
    return '<nav>' + " ".join(links) + '</nav>'


def render_page(title, body, prefix=""):
    template = (TEMPLATES / "page.html").read_text()
    return (
        template.replace("{{title}}", html.escape(title))
        .replace("{{nav}}", nav_html(prefix))
        .replace("{{stylesheet}}", f"{prefix}style.css")
        .replace("{{content}}", body)
    )

